  min-width: 40px;
  background: linear-gradient(180deg, #60a5fa, #2563eb);
  border-radius: 6px 6px 0 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  color: #fff;
  font-size: 0.7rem;
  padding: 0.25rem;
  text-align: center;
}

.chart-bar-label { font-weight: 600; }
.chart-bar-value { opacity: 0.9; }

