  width: 100%;
  border-collapse: collapse;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

#orders-table th,
#orders-table td {
  padding: 0.6rem 0.9rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

#orders-table th { background: #f0f2f5; font-size: 0.85rem; }
#orders-table td.order-amount { text-align: right; }

.empty-state {
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 8px;
  padding: 2rem;
  text-align: center;
  color: var(--muted);
}
"}

