args.content:
:root {
  --bg: #f5f6f8;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1f2933;
  --muted: #6b7280;
  --accent: #2563eb;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  padding: 2rem;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

#dashboard {
  max-width: 960px;
  margin: 0 auto;
}

h1 { font-size: 1.6rem; }
h2 { font-size: 1.15rem; margin-top: 2rem; }

#filter-form {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1.5rem;
}

.filter-fields {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.filter-fields label { font-size: 0.85rem; color: var(--muted); }

.filter-fields input[type="date"] {
  padding: 0.4rem 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
}

.filter-fields input[type="submit"] {
  padding: 0.45rem 1rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  font-size: 0.9rem;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1rem;
}

.metric-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.metric-label { font-size: 0.8rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.03em; }
.metric-value { font-size: 1.5rem; font-weight: 600; }

#chart {
  display: flex;
  align-items: flex-end;
  justify-content: flex-start;
  gap: 1.5rem;
  height: 260px;
  padding: 1rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
}

.chart-column {
  flex: 0 0 auto;
  width: 90px;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  gap: 0.4rem;
}

.chart-bar {
  width: 100%;
  min-height: 8px;
  background: linear-gradient(180deg, #60a5fa, #2563eb);
  border-radius: 6px 6px 0 0;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  color: #fff;
  font-size: 0.7rem;
  padding: 0.25rem;
  text-align: center;
}

.chart-bar-value { font-weight: 600; }

.chart-bar-label {
  font-size: 0.75rem;
  color: var(--muted);
  text-align: center;
  white-space: nowrap;
}

#orders-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

#orders-table th,
#orders-table td {
  padding: 0.6rem 0.9rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
}

#orders-table th { background: #f0f2f5; font-size: 0.85rem; }
#orders-table td.order-amount { text-align: right; }

.empty-state {
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 8px;
  padding: 2rem;
  text-align: center;
  color: var(--muted);
}
